itions\": [\"D009\"], \"source\": {\"declaration\": \"Real.volume_Icc\", \"hypotheses\": [], \"statement\": \"For all real a,b, λ([a,b])=max(b−a,0), viewed in [0,∞]; this is ENNReal.ofReal(b−a).\", \"module\": \"Mathlib.MeasureTheory.Measure.Lebesgue.Basic\", \"signature\": \"@Real.volume_Icc : ∀ {a b : ℝ}, Eq.{1} (MeasureTheory.volume.{0} (Set.Icc.{0} a b)) (ENNReal.ofReal (HSub.hSub.{0, 0, 0} b a))\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/MeasureTheory/Measure/Lebesgue/Basic.lean\", \"source_sha256\": \"72101050c59e99875b25c8cde0cebbcac53c99f569a4c5ab2d43a533d1f5fb8b\", \"evidence\": [{\"path\": \"library/M008-0008/library-sources.json\", \"sha256\": \"8dd7e0276c5fc81f01c8ca911d1d443b18e51f476eddea7a2b5161bc2ccecaa7\"}]}}, {\"id\": \"M009\", \"kind\": \"mathlib\", \"statement\": \"For all real a,b, λ((a,b))=max(b−a,0), viewed in [0,∞]; this is ENNReal.ofReal(b−a).\", \"binders\": [{\"symbol\": \"a\", \"type\": \"real number\"}, {\"symbol\": \"b\", \"type\": \"real number\"}], \"objects\": [\"a\", \"b\", \"λ\"], \"definitions\": [\"D009\"], \"source\": {\"declaration\": \"Real.volume_Ioo\", \"hypotheses\": [], \"statement\": \"For all real a,b, λ((a,b))=max(b−a,0), viewed in [0,∞]; this is ENNReal.ofReal(b−a).\", \"module\": \"Mathlib.MeasureTheory.Measure.Lebesgue.Basic\", \"signature\": \"@Real.volume_Ioo : ∀ {a b : ℝ}, Eq.{1} (MeasureTheory.volume.{0} (Set.Ioo.{0} a b)) (ENNReal.ofReal (HSub.hSub.{0, 0, 0} b a))\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/MeasureTheory/Measure/Lebesgue/Basic.lean\", \"source_sha256\": \"72101050c59e99875b25c8cde0cebbcac53c99f569a4c5ab2d43a533d1f5fb8b\", \"evidence\": [{\"path\": \"library/M009-0009/library-sources.json\", \"sha256\": \"66ce31d56ae55e10053540412900200b715d4fdb6bfdfbbfa1e329a6d7cf224b\"}]}}, {\"id\": \"M010\", \"kind\": \"mathlib\", \"statement\": \"For every type X, index type B, and type Q endowed with a faithful FunLike evaluation as functions Set(X)→[0,∞] and an OuterMeasureClass structure, every μ∈Q, every countable B, and every family A:B→Set(X), μ(⋃_i A_i)≤∑_i μ(A_i). An OuterMeasureClass means these functions vanish on the empty set, are monotone and are countably subadditive.\", \"binders\": [{\"symbol\": \"X\", \"type\": \"type\"}, {\"symbol\": \"B\", \"type\": \"index type\"}, {\"symbol\": \"Q\", \"type\": \"type of set-functions with FunLike and OuterMeasureClass structures\"}, {\"symbol\": \"μ\", \"type\": \"member of Q\"}, {\"symbol\": \"A\", \"type\": \"family B→Set(X)\"}], \"objects\": [\"X\", \"B\", \"Q\", \"μ\", \"A\"], \"definitions\": [], \"source\": {\"declaration\": \"MeasureTheory.measure_iUnion_le\", \"hypotheses\": [\"Q carries the stated FunLike and OuterMeasureClass structures on X.\", \"B is countable.\"], \"statement\": \"For every type X, index type B, and type Q endowed with a faithful FunLike evaluation as functions Set(X)→[0,∞] and an OuterMeasureClass structure, every μ∈Q, every countable B, and every family A:B→Set(X), μ(⋃_i A_i)≤∑_i μ(A_i). An OuterMeasureClass means these functions vanish on the empty set, are monotone and are countably subadditive.\", \"module\": \"Mathlib.MeasureTheory.OuterMeasure.Basic\", \"signature\": \"@MeasureTheory.measure_iUnion_le : ∀ {α : Type u_1} {ι : Type u_2} {F : Type u_3} [inst : FunLike.{u_3 + 1, u_1 + 1, 1} F (Set.{u_1} α) ENNReal]\\n  [MeasureTheory.OuterMeasureClass.{u_3, u_1} F α] {μ : F} [Countable.{u_2 + 1} ι] (s : ι → Set.{u_1} α),\\n  LE.le.{0} (μ (⋃ i, s i)) (∑' (i : ι), μ (s i))\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/MeasureTheory/OuterMeasure/Basic.lean\", \"source_sha256\": \"eb33f63fd442e930b4c907f091421830009407f956d3406a018daedaa64595e3\", \"evidence\": [{\"path\": \"library/M010-0011/library-sources.json\", \"sha256\": \"ab5452ed230e9a71773d6d9465c85be01d178d5a8d7185c9969eaa431aa8a200\"}]}}, {\"id\": \"M011\", \"kind\": \"mathlib\", \"statement\": \"For every measurable space X, every measure μ on X, and every f,g:X→[0,∞], pointwise f≤g implies ∫f dμ≤∫g dμ. Neither function is required measurable.\", \"binders\": [{\"symbol\": \"X\", \"type\": \"measurable space\"}, {\"symbol\": \"μ\", \"type\": \"measure on X\"}, {\"symbol\": \"f\", \"type\": \"function X→[0,∞]\"}, {\"symbol\": \"g\", \"type\": \"function X→[0,∞]\"}], \"objects\": [\"X\", \"μ\", \"f\", \"g\"], \"definitions\": [], \"source\": {\"declaration\": \"MeasureTheory.lintegral_mono\", \"hypotheses\": [\"X is a measurable space and μ is a measure on it.\", \"f≤g pointwise.\"], \"statement\": \"For every measurable space X, every measure μ on X, and every f,g:X→[0,∞], pointwise f≤g implies ∫f dμ≤∫g dμ. Neither function is required measurable.\", \"module\": \"Mathlib.MeasureTheory.Integral.Lebesgue.Basic\", \"signature\": \"@MeasureTheory.lintegral_mono : ∀ {α : Type u_1} {m : MeasurableSpace.{u_1} α} {μ : MeasureTheory.Measure.{u_1} α} ⦃f g : α → ENNReal⦄,\\n  LE.le.{u_1} f g → LE.le.{0} (∫⁻ (a : α), f a ∂μ) (∫⁻ (a : α), g a ∂μ)\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/MeasureTheory/Integral/Lebesgue/Basic.lean\", \"source_sha256\": \"b9a0715c48d4021f3e6bec2acdc6e5694d7fe4be082e4e0d17de04280a011559\", \"evidence\": [{\"path\": \"library/M011-0012/library-sources.json\", \"sha256\": \"5818e53052c339b24fef01a8d04241eaa191c8d380ee031321a86a4df051cc8b\"}]}}, {\"id\": \"M012\", \"kind\": \"mathlib\", \"statement\": \"For every pseudometric space X and compact subset A⊆X, A is bornologically bounded (belongs to the metric bornology of bounded sets).\", \"binders\": [{\"symbol\": \"X\", \"type\": \"pseudometric space\"}, {\"symbol\": \"A\", \"type\": \"subset of X\"}], \"objects\": [\"X\", \"A\"], \"definitions\": [], \"source\": {\"declaration\": \"IsCompact.isBounded\", \"hypotheses\": [\"X is a pseudometric space.\", \"A is compact.\"], \"statement\": \"For every pseudometric space X and compact subset A⊆X, A is bornologically bounded (belongs to the metric bornology of bounded sets).\", \"module\": \"Mathlib.Topology.MetricSpace.Bounded\", \"signature\": \"@IsCompact.isBounded : ∀ {α : Type u} [inst : PseudoMetricSpace.{u} α] {s : Set.{u} α}, IsCompact.{u} s → Bornology.IsBounded.{u} s\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Topology/MetricSpace/Bounded.lean\", \"source_sha256\": \"2c3c023949c19c45220a9ff8d08fe661521feeb85f7546e6f9133b0fdcc83b62\", \"evidence\": [{\"path\": \"library/M012-0013/library-sources.json\", \"sha256\": \"8ce36a3c869fe512767b9a3850366a9d36761b387d7558d2f93b0d77ea56625f\"}]}}, {\"id\": \"M013\", \"kind\": \"mathlib\", \"statement\": \"For every topological space X, compact subset A⊆X, arbitrary index type B and family U:B→Set(X), if every U_i is open and A⊆⋃_i U_i, then there is a finite set T⊆B such that A⊆⋃_{i∈T} U_i.\", \"binders\": [{\"symbol\": \"X\", \"type\": \"topological space\"}, {\"symbol\": \"A\", \"type\": \"subset of X\"}, {\"symbol\": \"B\", \"type\": \"index type\"}, {\"symbol\": \"U\", \"type\": \"family B→Set(X)\"}, {\"symbol\": \"T\", \"type\": \"finite subset of B\"}], \"objects\": [\"X\", \"A\", \"B\", \"U\", \"T\"], \"definitions\": [], \"source\": {\"declaration\": \"IsCompact.elim_finite_subcover\", \"hypotheses\": [\"X is a topological space.\", \"A is compact.\", \"Every U_i is open.\", \"A⊆⋃_i U_i.\"], \"statement\": \"For every topological space X, compact subset A⊆X, arbitrary index type B and family U:B→Set(X), if every U_i is open and A⊆⋃_i U_i, then there is a finite set T⊆B such that A⊆⋃_{i∈T} U_i.\", \"module\": \"Mathlib.Topology.Compactness.Compact\", \"signature\": \"@IsCompact.elim_finite_subcover : ∀ {X : Type u} [inst : TopologicalSpace.{u} X] {s : Set.{u} X} {ι : Type v},\\n  IsCompact.{u} s →\\n    ∀ (U : ι → Set.{u} X),\\n      (∀ (i : ι), IsOpen.{u} (U i)) → s ⊆ ⋃ i, U i → ∃ t, s ⊆ ⋃ i, ⋃ (_ : Membership.mem.{v, v} t i), U i\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Topology/Compactness/Compact.lean\", \"source_sha256\": \"4e0b10775666dd92f3b78bf408d7562d45eeac2af43aeee66982522b724e6261\", \"evidence\": [{\"path\": \"library/M013-0014/library-sources.json\", \"sha256\": \"ddc48959e1ff7c5502d2ed3e4ced0070d1673a1e9661d043368eec2a53ad110e\"}]}}, {\"id\": \"N001\", \"kind\": \"internal\", \"statement\": \"For every k∈ℕ, A⊆Eucl(k), s>0 and δ>0: (i) H^s(A)=Native(Eucl(k)).measure(s)(A); (ii) dim_H(A)≥0, H^s(A)=0 if s>dim_H(A), and H^s(A)=∞ if 0<s<dim_H(A); conversely H^s(A)=0 implies dim_H(A)≤s, and H^s(A)=∞ implies dim_H(A)≥s. Also H^s_δ(A) is nonincreasing as δ increases. H^s(A)=0 implies that at every positive scale and every positive cost threshold there is an admissible countable cover with cost below that threshold. H^s(A)=∞ implies that for every L>0 and δ0>0 there exists 0<δ≤δ0 with H^s_δ(A)>L.\", \"definitions\": [\"D001\", \"D002\", \"D003\", \"D004\", \"D005\"], \"binders\": [{\"symbol\": \"k\", \"type\": \"natural number\"}, {\"symbol\": \"A\", \"type\": \"subset of Eucl(k)\"}, {\"symbol\": \"s\", \"type\": \"positive real number\"}, {\"symbol\": \"δ\", \"type\": \"positive real number\"}, {\"symbol\": \"L\", \"type\": \"positive real number\"}, {\"symbol\": \"δ0\", \"type\": \"positive real number\"}], \"objects\": [\"k\", \"A\", \"s\", \"δ\", \"L\", \"δ0\", \"Eucl\", \"diam\", \"H\", \"Native\", \"dim_H\"], \"origin\": \"Native normalization and critical-exponent bridge for problem.md:34–47.\"}, {\"id\": \"N002\", \"kind\": \"internal\", \"statement\": \"E is bounded; there is R>0 with E⊆[−R,R]^n. For every s>0 and δ>0 there exists a finite cover of E by balls of diameter≤δ, of finite total s-cost; consequently H^s_δ(E)<∞. Also 0≤D≤n, so D is finite. If n=0 then E=Eucl(0) is a singleton and D=0.\", \"definitions\": [\"D001\", \"D002\", \"D003\", \"D005\", \"D008\"], \"binders\": [{\"symbol\": \"R\", \"type\": \"positive real number\"}, {\"symbol\": \"s\", \"type\": \"positive real exponent\"}, {\"symbol\": \"δ\", \"type\": \"positive real scale\"}], \"objects\": [\"E\", \"n\", \"D\", \"Eucl\", \"diam\", \"H\", \"R\", \"s\", \"δ\"], \"origin\": \"Boundedness, finite scale costs and ambient-dimension calculation, problem.md:49–57,130–131.\"}, {\"id\": \"N003\", \"kind\": \"internal\", \"statement\": \"For every nonempty B⊆ℝ, every finite ρ≥0 with |b−b'|≤ρ for all b,b'∈B, and every η>0, B is contained in the bounded open interval J=(inf B−η/2,sup B+η/2), whose length |J| is≤ρ+η. The endpoints exist as real numbers, and the construction also applies when ρ=0.\", \"definitions\": [\"D009\"], \"binders\": [{\"symbol\": \"B\", \"type\": \"subset of ℝ\"}, {\"symbol\": \"ρ\", \"type\": \"finite nonnegative real number\"}, {\"symbol\": \"η\", \"type\": \"positive real number\"}, {\"symbol\": \"b\", \"type\": \"point of B\"}, {\"symbol\": \"b'\", \"type\": \"point of B\"}, {\"symbol\": \"J\", \"type\": \"bounded open interval in ℝ\"}], \"objects\": [\"B\", \"ρ\", \"η\", \"b\", \"b'\", \"J\", \"λ\"], \"origin\": \"Open-interval enclosure used in problem.md:116–119 and159–161.\"}, {\"id\": \"N004\", \"kind\": \"internal\", \"statement\": \"dim_H(F)≤D+1. More precisely, for every q>D and δ>0, H^(q+1)_δ(F)=0 and H^(q+1)(F)=0.\", \"definitions\": [\"D001\", \"D003\", \"D005\", \"D007\", \"D008\"], \"binders\": [{\"symbol\": \"q\", \"type\": \"real number\"}, {\"symbol\": \"δ\", \"type\": \"positive real scale\"}], \"objects\": [\"F\", \"D\", \"dim_H\", \"H\", \"q\", \"δ\"], \"origin\": \"Upper bound by subdividing each cover cylinder, problem.md:59–92.\"}, {\"id\": \"N005\", \"kind\": \"internal\", \"statement\": \"For every real s>0 and scale δ>0, H^s_δ(E)≤H^(s+1)_δ(F).\", \"definitions\": [\"D003\", \"D007\"], \"binders\": [{\"symbol\": \"s\", \"type\": \"positive real exponent\"}, {\"symbol\": \"δ\", \"type\": \"positive real scale\"}], \"objects\": [\"s\", \"δ\", \"E\", \"F\", \"H\"], \"origin\": \"Integrated slice-cover inequality (1), problem.md:96–148.\"}, {\"id\": \"N006\", \"kind\": \"internal\", \"statement\": \"dim_H(I)=1. For every 0<s<1, H^s(I)=∞. For every k∈ℕ, A⊆Eucl(k), and map e:I→Eucl(k) with e(I)⊆A and dist(e(t),e(u))=|t−u| for all t,u∈I, dim_H(A)≥1. More precisely H^s_δ(I)≤H^s_δ(A) for every s>0 and δ>0 under these embedding conditions.\", \"definitions\": [\"D001\", \"D002\", \"D003\", \"D005\", \"D006\"], \"binders\": [{\"symbol\": \"s\", \"type\": \"real exponent\"}, {\"symbol\": \"k\", \"type\": \"natural number\"}, {\"symbol\": \"A\", \"type\": \"subset of Eucl(k)\"}, {\"symbol\": \"e\", \"type\": \"map I→Eucl(k)\"}, {\"symbol\": \"t\", \"type\": \"point of I\"}, {\"symbol\": \"u\", \"type\": \"point of I\"}, {\"symbol\": \"δ\", \"type\": \"positive real scale\"}], \"objects\": [\"I\", \"H\", \"dim_H\", \"k\", \"A\", \"Eucl\", \"e\", \"t\", \"u\", \"s\", \"δ\"], \"origin\": \"Interval dimension and isometric-image comparison, problem.md:153–165, with the covering proof of monotonicity made explicit.\"}, {\"id\": \"P\", \"kind\": \"target\", \"definitions\": [\"D001\", \"D005\", \"D006\", \"D007\", \"D008\"], \"binders\": [], \"objects\": [\"n\", \"E\", \"F\", \"D\", \"I\", \"Eucl\", \"dim_H\"], \"statement\": \"dim_H(E×[0,1])=dim_H(E)+1, with E×[0,1]=F in the Euclidean space Eucl(n+1).\"}, {\"id\": \"M014\", \"kind\": \"mathlib\", \"statement\": \"For every real y<0, the real function x↦x^y tends to +∞ as x tends to zero through strictly positive real values.\", \"definitions\": [], \"binders\": [{\"symbol\": \"y\", \"type\": \"real number\"}, {\"symbol\": \"x\", \"type\": \"real variable of the displayed function\"}], \"objects\": [\"y\", \"x\"], \"source\": {\"declaration\": \"tendsto_rpow_neg_nhdsGT_zero\", \"hypotheses\": [\"y<0.\"], \"statement\": \"For every real y<0, the real function x↦x^y tends to +∞ as x tends to zero through strictly positive real values.\", \"module\": \"Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics\", \"signature\": \"@tendsto_rpow_neg_nhdsGT_zero : ∀ {y : ℝ},\\n  LT.lt.{0} y 0 →\\n    Filter.Tendsto.{0, 0} (fun x => HPow.hPow.{0, 0, 0} x y) (nhdsWithin.{0} 0 (Set.Ioi.{0} 0)) Filter.atTop.{0}\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Analysis/SpecialFunctions/Pow/Asymptotics.lean\", \"source_sha256\": \"004e4d6013b20f95feedfcb23b257c07eb1ee4c7645b9d81fd6e4cb684a116d6\", \"evidence\": [{\"path\": \"library/M014-0015/library-sources.json\", \"sha256\": \"60eec80d77e0f2fd98f7d942ca4fad425b8f3956d4a96c496fc9c783111d0633\"}]}}, {\"id\": \"M015\", \"kind\": \"mathlib\", \"statement\": \"For every real y>0, the real function x↦x^(−y) tends to zero as x tends to +∞.\", \"definitions\": [], \"binders\": [{\"symbol\": \"y\", \"type\": \"real number\"}, {\"symbol\": \"x\", \"type\": \"real variable of the displayed function\"}], \"objects\": [\"y\", \"x\"], \"source\": {\"declaration\": \"tendsto_rpow_neg_atTop\", \"hypotheses\": [\"0<y.\"], \"statement\": \"For every real y>0, the real function x↦x^(−y) tends to zero as x tends to +∞.\", \"module\": \"Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics\", \"signature\": \"@tendsto_rpow_neg_atTop : ∀ {y : ℝ},\\n  LT.lt.{0} 0 y → Filter.Tendsto.{0, 0} (fun x => HPow.hPow.{0, 0, 0} x (Neg.neg.{0} y)) Filter.atTop.{0} (nhds.{0} 0)\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Analysis/SpecialFunctions/Pow/Asymptotics.lean\", \"source_sha256\": \"004e4d6013b20f95feedfcb23b257c07eb1ee4c7645b9d81fd6e4cb684a116d6\", \"evidence\": [{\"path\": \"library/M015-0016/library-sources.json\", \"sha256\": \"46dcf871407a9345df018d3c3c93f45b4988e808d396e1617fed74a2ac33a0e9\"}]}}, {\"id\": \"M016\", \"kind\": \"mathlib\", \"statement\": \"For every nonempty subset B of ℝ which is bounded above, there is a real number b which is a least upper bound of B: every element of B is≤b, and b is≤every upper bound of B.\", \"definitions\": [], \"binders\": [{\"symbol\": \"B\", \"type\": \"subset of ℝ\"}, {\"symbol\": \"b\", \"type\": \"real number\"}], \"objects\": [\"B\", \"b\"], \"source\": {\"declaration\": \"Real.exists_isLUB\", \"hypotheses\": [\"B is nonempty.\", \"B is bounded above.\"], \"statement\": \"For every nonempty subset B of ℝ which is bounded above, there is a real number b which is a least upper bound of B: every element of B is≤b, and b is≤every upper bound of B.\", \"module\": \"Mathlib.Algebra.Order.Archimedean.Real.Basic\", \"signature\": \"@Real.exists_isLUB : ∀ {s : Set.{0} ℝ}, Set.Nonempty.{0} s → BddAbove.{0} s → ∃ x, IsLUB.{0} s x\", \"declaration_kind\": \"theorem\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"source_path\": \"Mathlib/Algebra/Order/Archimedean/Real/Basic.lean\", \"source_sha256\": \"ba51e7d1078ee669a1b5e95968163937113d8ba729e9f2fb7e6ed0ebd66acfd0\", \"evidence\": [{\"path\": \"library/M016-0019/library-sources.json\", \"sha256\": \"e737db8be5278468e3cb18cba612962b2636daa32c1e4d3f27d12f7f53a53196\"}]}}, {\"id\": \"M017\", \"kind\": \"mathlib\", \"statement\": \"For every nonempty subset B of ℝ which is bounded below, there is a real number b which is a greatest lower bound of B: b is≤every element of B, and every lower bound of B is≤b.\", \"definitions\": [], \"binders\": [{\"symbol\": \"B\", \"type\": \"subset of ℝ\"}, {\"symbol\": \"b\", \"type\": \"real number\"}], \"objects\": [\"B\", \"b\"], \"source\": {\"declaration\": \"Real.exists_isGLB\", \"hypotheses\": [\"B is nonempty.\", \"B is bounded below.\"], \"statement\": \"For every nonempty subset B of ℝ which is bounded below, there is a real number b which is a greatest lower bound of B: b is≤every element 